// Master router — Watchdog owns ops routing.
// Daily OS = Grok Bot + Cursor. n8n only fans out to hive webhooks on evenslouis.ca.
// Philanthropy :3002 and OpenClaw :18789 are HOLD — never route there as hard-fail gates.
// Prefer catalog `route` key; keep signalType as a legacy alias.
const body = $json.body || $json;
const routeKey = body.route || body.signalType || body.signal_type || body.type || 'unknown';
const source = body.source || body.sourceRepo || 'unknown';
const correlationId = body.correlationId || body.correlation_id || `eco-${Date.now()}`;

const ROUTE_MAP = {
  'golden-path-smoke': 'https://evenslouis.ca/webhook/hive-golden-path-smoke',
  'golden-path': 'https://evenslouis.ca/webhook/hive-golden-path-smoke',
  'error-heal': 'https://evenslouis.ca/webhook/hive-error-heal',
  'outer-heaven-report': 'https://evenslouis.ca/webhook/hive-outer-heaven-report',
  'market-signal': 'https://evenslouis.ca/webhook/hive-market-signal',
  'ce-lead-notify': 'https://evenslouis.ca/webhook/hive-ce-lead-notify',
  'ce-lead': 'https://evenslouis.ca/webhook/hive-ce-lead-notify',
  'founder-signal': 'https://evenslouis.ca/webhook/hive-founder-signal',
  'meta-critique': 'https://evenslouis.ca/webhook/hive-meta-critique',
  'predictive-construct': 'https://evenslouis.ca/webhook/hive-predictive-construct',
  'chronicle-ingest': 'https://evenslouis.ca/webhook/hive-chronicle-ingest',
  'telemetry-ingest': 'https://evenslouis.ca/webhook/hive-telemetry-ingest',
  'disk-alert': 'https://evenslouis.ca/webhook/hive-disk-alert',
  'ops-alert': 'https://evenslouis.ca/webhook/hive-error-heal'
};

const targetUrl = ROUTE_MAP[routeKey] || null;
const forwardBody = {
  correlationId,
  sourceRepo: body.sourceRepo || source,
  lane: body.lane || 'hive-os',
  ...(body.payload && typeof body.payload === 'object' ? body.payload : {}),
  ...(body.payload ? {} : Object.fromEntries(Object.entries(body).filter(([k]) => !['route', 'signalType', 'signal_type', 'type', '_routing'].includes(k))))
};

return [{
  json: {
    ...body,
    correlationId,
    _routing: {
      routeKey,
      source,
      targetUrl,
      resolved: targetUrl !== null,
      routeMap: Object.keys(ROUTE_MAP),
      forwardBody,
      hostsForbidden: ['n8ncloud.tech', '127.0.0.1:3002', '127.0.0.1:18789']
    }
  }
}];

// Soft-handle unregistered/inactive/HOLD targets. Never fail the hive on Telegram or down hosts.
const input = $input.first().json;
const routing = $('Resolve Route').first().json._routing || {};
const statusCode = input.statusCode || input.code || null;
const error = input.error || input.message || null;

if (statusCode === 401) {
  return [{
    json: {
      forwarded: false,
      error: `Target returned 401. Operator HITL — do not invent credentials. Use existing HIVE_WEBHOOK_SECRET as X-Hive-Secret.`,
      hint: 'Philanthropy :3002 and OpenClaw :18789 are HOLD. Telegram is optional/legacy.',
      targetUrl: routing.targetUrl,
      correlationId: routing.forwardBody && routing.forwardBody.correlationId
    }
  }];
}

if (statusCode === 404 || error) {
  return [{
    json: {
      forwarded: false,
      error: `Target webhook returned ${statusCode || 'error'}: ${error || 'Not Found'}. Target may be inactive, planned, or not yet imported.`,
      hint: 'Watchdog/operator import HITL. Do not activate-all. Do not treat as a second daily OS.',
      targetUrl: routing.targetUrl,
      originalPayload: routing.forwardBody
    }
  }];
}

return [{
  json: {
    forwarded: true,
    response: input,
    correlationId: routing.forwardBody && routing.forwardBody.correlationId
  }
}];

const routing = $json._routing || {};
return [{
  json: {
    forwarded: false,
    error: `No route found for '${routing.routeKey}'. Known routes: ${(routing.routeMap || []).join(', ')}`,
    hint: 'Pass catalog `route` (preferred) or legacy signalType. Email/calendar/day-plan stay on Grok — not routed here.'
  }
}];
